16	public class ValidationExceptionHandler {
17	
18	    public void handle(@Parameter MethodArgumentNotValidException ex,
19	            ObjectResponse<ResponseEntity<ProblemDetail>> response) {
20	        ProblemDetail detail = ProblemDetails.build(ex, HttpStatus.BAD_REQUEST,
21	                "The request contains invalid or missing parameters");
22	        BindingResult bindingResult = ex.getBindingResult();
23	        if (bindingResult.hasErrors()) {
24	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
25	                    .map(fieldError -> {
26	                        String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
27	                        String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
28	                        String message = "Field '%s' %s (rejected value: %s)".formatted(
29	                                fieldError.getField(), defaultMessage, rejectedValue);
30	                        return new ValidationMessageDto(message)
31	                                .putAdditionalProperty("field", fieldError.getField())
32	                                .putAdditionalProperty("rejectedValue", rejectedValue)
33	                                .putAdditionalProperty("defaultMessage", defaultMessage);
34	                    })
35	                    .toList();
36	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
37	            detail.setProperty("errors", bindingResult.getFieldErrors().stream()
38	                    .map(FieldError::getField).distinct().toList());
39	        }
40	        response.send(ResponseEntity.status(HttpStatus.BAD_REQUEST).body(detail));
41	    }
42	}
